13	import { useUIState } from '../../contexts/UIStateContext.js';
14	import { useAlternateBuffer } from '../../hooks/useAlternateBuffer.js';
15	import { OverflowProvider } from '../../contexts/OverflowContext.js';
16	
17	interface GeminiMessageProps {
18	  text: string;
19	  isPending: boolean;
20	  availableTerminalHeight?: number;
21	  terminalWidth: number;
22	}
23	
24	export const GeminiMessage: React.FC<GeminiMessageProps> = ({
25	  text,
26	  isPending,
27	  availableTerminalHeight,
28	  terminalWidth,
29	}) => {
30	  const { renderMarkdown } = useUIState();
31	  const prefix = '✦ ';
32	  const prefixWidth = prefix.length;
33	
34	  const isAlternateBuffer = useAlternateBuffer();
35	  const content = (
36	    <Box flexDirection="row">
37	      <Box width={prefixWidth}>
38	        <Text color={theme.text.accent} aria-label={SCREEN_READER_MODEL_PREFIX}>
39	          {prefix}
40	        </Text>
41	      </Box>
42	      <Box flexGrow={1} flexDirection="column">
43	        <MarkdownDisplay
44	          text={text}
45	          isPending={isPending}
46	          availableTerminalHeight={
47	            isAlternateBuffer || availableTerminalHeight === undefined
48	              ? undefined
49	              : Math.max(availableTerminalHeight - 1, 1)
50	          }
51	          terminalWidth={Math.max(terminalWidth - prefixWidth, 0)}
52	          renderMarkdown={renderMarkdown}
53	        />
54	        <Box
55	          marginTop={isAlternateBuffer ? 0 : 1}
56	          marginBottom={isAlternateBuffer ? 1 : 0}
57	        >
58	          <ShowMoreLines
59	            constrainHeight={availableTerminalHeight !== undefined}
60	          />
61	        </Box>
62	      </Box>
63	    </Box>
64	  );
65	
66	  return isAlternateBuffer ? (
67	    /* Shadow the global provider to maintain isolation in ASB mode. */
68	    <OverflowProvider>{content}</OverflowProvider>
69	  ) : (
70	    content
71	  );
72	};
